function squeezeNodes(nodes: DocsNode[]): DocsNode[] {
  while (nodes.length === 1 && isDocsHierarchy(nodes[0])) {
    nodes = nodes[0].contents;
  }
  return nodes;
}

function docsNodesToPages(nodes: DocsNode[]): Page[] {
  return squeezeNodes(nodes).map((node) =>
    isDocsHierarchy(node)
      ? {
          name: node.title,
          to: { name: 'docs' },
          icon: FolderIcon,
          disabled: false,
          children: docsNodesToPages(node.contents),
        }
      : {
          name: node.title,
          to: docPathToRoute(node.path),
          icon: FileTextIcon,
          disabled: false,
        }
  );
}

export function useNavActive() {
  const route = useRoute();

  function isCurrent(page: Page, ignoreParents: boolean = true): boolean {
    if (ignoreParents && page.children?.length) return false;
    const to = page.to;
    if (typeof to === 'string') return route.path === to;
    return Boolean(to.name && route.name?.startsWith(to.name as string));
  }
  function isActive(page: Page): boolean {
    return isCurrent(page) || (page.children?.some(isActive) ?? false);
  }
  function isChildActive(page: Page): boolean {
    return page.children?.some(isActive) ?? false;
  }

  function getActiveChain_(page: Page): Page[] | undefined {
    if (isCurrent(page)) {
      return [page];
    }
    if (page.children) {
      for (const child of page.children) {
        const childIndexes = getActiveChain_(child);
        if (childIndexes) {
          return [page, ...childIndexes];
        }
      }
    }
    return undefined;
  }

  function getActiveChain(pages: Page[]): Page[] {
    for (const page of pages) {
      const pageChain = getActiveChain_(page);
      if (pageChain) {
        return pageChain;
      }
    }
    return [];
  }

  return { isActive, isCurrent, isChildActive, getActiveChain };
}

export function useNavPages(chatBadge?: ComputedRef<string>, notificationBadge?: ComputedRef<string>) {
  const router = useRouter();
  const { isCanvasser, isCanvasserOrSubCanvasser, userRole, accountProblems, isAdminOrManager } = useUserRole();
  const { isMobile } = useMobileForWeb();

  const chatBadgeValue = computed(() => chatBadge?.value ?? '');
  const notificationBadgeValue = computed(() => notificationBadge?.value ?? '');

  const { data: docPages, isLoading: isLoadingDocPages } = useQuery({
    key: () => ['docs-list'],
    query: () => getDocsList({}),
  });

  const tree = computed(() => groupGuides(docPages.value?.pages ?? []));

  const pages = computed<Page[]>(() => [
    {
      name: isCanvasserOrSubCanvasser.value ? 'My Projects' : 'Projects',
      to: { name: 'projects' },
      icon: Briefcase,
      disabled: false,
    },
    {
      name: 'My Shifts',
      to: { name: 'shift' },
      icon: Clock,
      disabled: false,
      hidden: !isCanvasserOrSubCanvasser.value || !isMobile,
    },
    {
      name: 'Chats',
      to: { name: 'chats' },
      icon: MessageSquareText,
      disabled: false,
    },
    {
      name: 'Verification',
      to: { name: isAdminOrManager.value ? 'verification-ballots' : 'verification' },
      icon: BadgeCheck,
      disabled: false,
    },
    {
      name: 'My Applications',
      to: { name: 'applications' },
      icon: NotepadText,
      disabled: false,
      hidden: !isCanvasser.value,
    },
    {
      name: 'Earnings',
      to: { name: isCanvasser.value ? 'earnings-balance' : 'earnings' }, //page disabled for sub-canvassers as they don't have access to earnings and they don't see button at all
      icon: DollarSign,
      disabled: false,
    },
    { name: 'Users', to: { name: 'users' }, icon: UsersRound, disabled: false },
    { name: 'Staffing', to: { name: 'staffing-resources' }, icon: BookUser, disabled: false },
    { name: 'Recruitment', to: { name: 'recruitment' }, icon: Mail, disabled: false },
    {
      name: 'Subcontractors',
      to: { name: 'subcontractor-companies' },
      icon: Building2,
      disabled: false,
    },
    {
      name: 'My Account',
      to: { name: 'account' },
      icon: UserRound,
      problems: accountProblems.value?.alert_counters.account,
      disabled: false,
      inUserMenu: true,
    },
    {
      name: 'Notifications',
      to: { name: 'notifications' },
      icon: Bell,
      disabled: false,
      inUserMenu: true,
    },
    { name: 'System Settings', to: { name: 'system-settings' }, icon: Settings, disabled: false },
    {
      name: 'More',
      to: { name: 'tools' },
      icon: Ellipsis,
      disabled: false,
      children: [
        { name: 'Work Shifts', to: { name: 'workshifts' }, icon: Clock, disabled: false },
        {
          name: 'Canvassing Imports',
          to: { name: 'canvassing-interaction-imports' },
          icon: FileClock,
          disabled: false,
        },
        { name: 'Reports', to: { name: 'reports' }, icon: FileTextIcon, disabled: false },
        { name: 'Conversations', to: { name: 'conversations' }, icon: Speech, disabled: false },
        { name: 'Coaching Feedbacks', to: { name: 'coaching-feedbacks' }, icon: MessageCircle, disabled: false },
        { name: 'Emergencies', to: { name: 'emergencies' }, icon: Siren, disabled: false },
        { name: 'Contracts', to: { name: 'contracts' }, icon: FileSignature, disabled: false },
        { name: 'System Dashboard', to: { name: 'system-dashboard' }, icon: LayoutDashboard, disabled: false },
        {
          name: 'Applications',
          to: { name: 'applications' },
          icon: NotepadText,
          disabled: false,
          hidden: isCanvasser.value,
        },
        {
          name: 'Help',
          to: { name: 'docs' },
          icon: CircleHelp,
          disabled: false,
          isSlideOver: true,
          isLoading: isLoadingDocPages.value,
          hidden: !isLoadingDocPages.value && tree.value.length === 0,
          children: docsNodesToPages(tree.value),
        },
      ],
    },
  ]);

  const filteredPages = computed(() => {
    const availableRoutes = router.getRoutes().filter((route) => {
      const roles = Array.isArray(route.meta?.roles) ? route.meta?.roles : undefined;

      if (!roles) return true;
      return roles.includes(userRole.value);
    });

    const isVisible = (page: Page) => !page.hidden && availableRoutes.some((route) => route.name === page.to.name);

    return pages.value
      .map((page) => {
        if (page.to.name === 'chats') page = { ...page, infoBadge: chatBadgeValue.value };
        if (page.to.name === 'notifications') page = { ...page, infoBadge: notificationBadgeValue.value };
        if (page.children) {
          const filteredChildren = page.children.filter(isVisible);
          if (filteredChildren.length === 0) return null;
          return { ...page, children: filteredChildren };
        }
        return isVisible(page) ? page : null;
      })
      .filter(Boolean) as Page[];
  });

  const sidebarPages = computed(() => filteredPages.value.filter((page) => !page.inUserMenu));

  return {
    filteredPages,
    sidebarPages,
  };
}
